docker images -q alpine-zip | grep -q . || docker build -t alpine-zip -f AlpineZipDockerfile .

docker run --rm -v mysql-app_persistence_db_app_rm:/data -v "$(pwd)/mysql-app":/backup alpine-zip sh -c "cd /backup && [ -f mysql-app_persistence_db_app_rm.zip ] && rm -f mysql-app_persistence_db_app_rm.zip mysql-app_persistence_db_app_rm.z*; cd /data && zip -s 48m -r /backup/mysql-app_persistence_db_app_rm.zip ."
